from typing import List
from collections import deque

def findShortestPath(matrix: List[List[int]]) -> int:
    if not matrix or not matrix[0]:
        return -1

    rows = len(matrix)
    cols = len(matrix[0])

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Check if a cell is safe (1) and not adjacent to any landmine (0)
    def is_safe(r, c):
        if matrix[r][c] == 0:
            return False
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and matrix[nr][nc] == 0:
                return False
        return True

    # BFS setup
    queue = deque()
    visited = [[False for _ in range(cols)] for _ in range(rows)]

    # Initialize queue with all safe cells in the first column
    for r in range(rows):
        if is_safe(r, 0):
            queue.append((r, 0, 1))  # (row, col, steps)
            visited[r][0] = True

    if not queue:
        return -1

    while queue:
        r, c, steps = queue.popleft()

        # Check if reached last column
        if c == cols - 1:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and is_safe(nr, nc):
                visited[nr][nc] = True
                queue.append((nr, nc, steps + 1))

    return -1
